import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;

public class ZonedDateTimeExample {
    public static void main(String[] args) {
        // Capture the current moment in a specific time zone
        ZonedDateTime zdtNewYork = ZonedDateTime.now(ZoneId.of("America/New_York"));

        // Convert the exact same physical moment to Tokyo time
        ZonedDateTime zdtTokyo = zdtNewYork.withZoneSameInstant(ZoneId.of("Asia/Tokyo"));

        System.out.println("New York: " + zdtNewYork.format(DateTimeFormatter.ISO_ZONED_DATE_TIME));
        System.out.println("Tokyo:    " + zdtTokyo.format(DateTimeFormatter.ISO_ZONED_DATE_TIME));
    }
}
